"""Scalar C++17 subsystem transport, built only inside the nonroot worker."""
from pathlib import Path
import os
import subprocess
import sys

_BINARY=None

def build():
    global _BINARY
    if _BINARY is None:
        root=Path(__file__).resolve().parent
        scratch=Path('/workspace/tmp')
        _BINARY=scratch/('lookup-'+str(os.getpid()))
        env=dict(os.environ,TMPDIR=str(scratch))
        subprocess.run(['g++','-O2','-std=c++17',str(root/'engine.cpp'),'-o',str(_BINARY)],
                       check=True,env=env)
    return _BINARY

def run(lines):
    result=subprocess.run([str(build())],input=('\n'.join(lines)+'\n').encode(),
                          stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False)
    if result.returncode:
        sys.stderr.buffer.write(result.stderr)
        raise RuntimeError('native stage failed')
    return result.stdout.decode().splitlines()

def atlas(routes):
    lines=['ATLAS '+str(len(routes))]
    lines += [f'{start:032x} {length} {hop}' for (start,length),hop in routes.items()]
    result=run(lines)
    if len(result)!=1+int(result[0]):raise RuntimeError('native atlas framing')
    rows=[line.split() for line in result[1:]]
    return [int(a,16) for a,h in rows],[None if h=='-1' else int(h) for a,h in rows]

def pack(starts,hops,tree,addresses):
    nodes=[tree]
    for node in nodes:nodes.extend(node['children'])
    indices={id(n):i for i,n in enumerate(nodes)}
    lines=[f'PACK {len(starts)} {len(nodes)} {len(addresses)}']
    lines += [f'{x:032x} {-1 if h is None else h}' for x,h in zip(starts,hops)]
    for node in nodes:
        children=[indices[id(c)] for c in node['children']]
        row=[node['lo'],node['span'],node['mode'],node['cached'],len(children),*children]
        lines.append(' '.join(map(str,row)))
    lines += [f'{x:032x}' for x in addresses]
    output=run(lines)
    if len(output)!=len(addresses)+1:raise RuntimeError('native pack framing')
    answers=[]
    for line in output[1:]:
        hop,rank,count,*path=map(int,line.split())
        if count!=len(path):raise RuntimeError('native path framing')
        answers.append([None if hop==-1 else hop,rank,path])
    return output[0],answers

def trace(image,addresses):
    rows=run(['TRACE '+str(len(addresses)),image,*[f'{x:032x}' for x in addresses]])
    if len(rows)!=len(addresses):raise RuntimeError('native trace framing')
    answers=[]
    for row in rows:
        hop,rank,count,*path=map(int,row.split())
        if count!=len(path):raise RuntimeError('native trace path framing')
        answers.append([None if hop==-1 else hop,rank,path])
    return answers
"""Strict request syntax and normalized full-width addresses, protocol 2."""
import ipaddress
import json
import re

MAX_INPUT = 16 * 1024 * 1024


class Invalid(ValueError):
    pass


def unique_object(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid("duplicate key")
        obj[key] = value
    return obj


def nonfinite(_):
    raise Invalid("nonfinite JSON")


def keys(value, names):
    if type(value) is not dict or set(value) != set(names):
        raise Invalid("object shape")


def array(value):
    if type(value) is not list:
        raise Invalid("array required")
    return value


def integer(value, low, high):
    if type(value) is not int or not low <= value <= high:
        raise Invalid("integer range")
    return value


def address(value):
    if (type(value) is not str or not 1 <= len(value) <= 64
            or re.fullmatch(r"[0-9a-fA-F:]+", value) is None):
        raise Invalid("IPv6 address")
    try:
        return int(ipaddress.IPv6Address(value))
    except ValueError as exc:
        raise Invalid("IPv6 address") from exc


def prefix(value):
    if type(value) is not str or len(value) > 64 or value.count("/") != 1:
        raise Invalid("prefix")
    addr, length = value.split("/")
    if re.fullmatch(r"0|[1-9][0-9]*", length) is None:
        raise Invalid("prefix length")
    length = integer(int(length), 0, 128)
    size = 1 << (128 - length)
    return address(addr) // size * size, length


def parse_request(data):
    if len(data) > MAX_INPUT:
        raise Invalid("input byte budget")
    try:
        request = json.loads(data.decode("utf-8"), object_pairs_hook=unique_object,
                             parse_constant=nonfinite)
    except (ValueError, UnicodeError, RecursionError) as exc:
        raise Invalid("JSON") from exc
    keys(request, ["cases"])
    cases = array(request["cases"])
    if len(cases) > 4:
        raise Invalid("case budget")
    rows = version_entries = query_count = burst_count = 0
    normalized = []
    for case in cases:
        keys(case, ["initial", "transactions", "bursts", "cache_pages", "costs"])
        cache = integer(case["cache_pages"], 0, 12)
        costs = case["costs"]
        keys(costs, ["hit", "miss", "decode"])
        hit = integer(costs["hit"], 1, 16)
        miss = integer(costs["miss"], hit, 256)
        dec = array(costs["decode"])
        if len(dec) != 3:
            raise Invalid("decode costs")
        dec = [integer(x, 0, 16) for x in dec]
        initial = array(case["initial"])
        transactions = array(case["transactions"])
        bursts = array(case["bursts"])
        if len(transactions) > 7:
            raise Invalid("version budget")
        rows += len(initial)
        for tx in transactions:
            rows += len(array(tx))
        burst_count += len(bursts)
        if rows > 60000 or burst_count > 256:
            raise Invalid("batch budget")
        routes, init = set(), []
        for row in initial:
            if len(array(row)) != 2:
                raise Invalid("initial row")
            route, hop = prefix(row[0]), integer(row[1], 0, 2147483647)
            init.append((route, hop))
            routes.add(route)
            if len(routes) > 30000:
                raise Invalid("active route budget")
        version_entries += len(routes)
        txs = []
        for tx in transactions:
            out = []
            for change in tx:
                change = array(change)
                if not change or type(change[0]) is not str:
                    raise Invalid("change")
                op = change[0]
                if op == "set" and len(change) == 3:
                    route = prefix(change[1])
                    hop = integer(change[2], 0, 2147483647)
                    routes.add(route)
                    out.append((op, route, hop))
                elif op == "erase" and len(change) == 2:
                    route = prefix(change[1])
                    routes.discard(route)
                    out.append((op, route, None))
                else:
                    raise Invalid("change")
                if len(routes) > 30000:
                    raise Invalid("active route budget")
            txs.append(out)
            version_entries += len(routes)
        if version_entries > 60000:
            raise Invalid("committed route-entry budget")
        queries = []
        for burst in bursts:
            keys(burst, ["version", "repeat", "addresses"])
            version = integer(burst["version"], 0, len(transactions))
            repeat = integer(burst["repeat"], 1, 1000000)
            addresses = array(burst["addresses"])
            query_count += len(addresses)
            if len(addresses) > 64 or query_count > 8192:
                raise Invalid("address budget")
            queries.append((version, repeat, [address(x) for x in addresses]))
        normalized.append({"initial": init, "transactions": txs, "bursts": queries,
                           "cache_pages": cache, "costs": (hit, miss, dec)})
    return normalized
